mapper.sql:
WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL
AND r.biz_code = #{bizCode}
AND r.namespace_id = #{namespaceId}
AND r.env_code = #{envCode}
AND r.app_code = #{appCode}
AND r.kind = #{kind}

    AND r.tags_json::jsonb @> jsonb_build_array(#{tag})


    AND (
        r.resource_key ILIKE CONCAT('%', #{keyword}, '%')
        OR r.display_name ILIKE CONCAT('%', #{keyword}, '%')
        OR r.description ILIKE CONCAT('%', #{keyword}, '%')
        OR r.search_tsv @@ plainto_tsquery('simple', #{keyword})
    )

mapper.select:
SELECT 
FROM ddc_si_resource
WHERE tenant_id = #{tenantId} AND biz_code = #{bizCode} AND namespace_id = #{namespaceId}
  AND env_code = #{envCode} AND app_code = #{appCode} AND kind = #{kind}
  AND resource_key = #{resourceKey} AND deleted_at IS NULL

SELECT count(*)
FROM ddc_si_resource r

AND r.lifecycle_status = #{lifecycleStatus}
